import java.util.*;
public class Main {
    static class Node { String name; List<Node> neighbors = new ArrayList<>(); Node(String name) { this.name = name; } }
    public static void main(String[] args) {
        Node a = new Node("A"), b = new Node("B"), c = new Node("C");
        a.neighbors.add(b); a.neighbors.add(c); b.neighbors.add(c); c.neighbors.add(a);
        Set<String> seen = new HashSet<>();
        Queue<Node> queue = new ArrayDeque<>(); queue.add(a);
        while (!queue.isEmpty()) { Node n = queue.remove(); if (seen.add(n.name)) queue.addAll(n.neighbors); }
        System.out.println(seen.size() + " " + (a.neighbors.get(1) == c) + " " + (c.neighbors.get(0) == a));
    }
}
